import { Box, Typography, Card, CardContent, Tooltip } from '@mui/material';
import { TrendingUp, Crosshair, Target, Activity, HelpCircle } from 'lucide-react';

const METRICS = [
  { key: 'accuracy', label: 'Accuracy', desc: 'Taux de prédictions correctes — 75.37% des produits sont correctement classés comme recommandables ou non.', icon: TrendingUp, color: '#f97316' },
  { key: 'precision', label: 'Precision', desc: 'Quand le modèle recommande un produit, il a raison 60.51% du temps. Évite les fausses recommandations.', icon: Crosshair, color: '#6366f1' },
  { key: 'recall', label: 'Recall', desc: 'Le modèle détecte 50.12% de tous les produits réellement recommandables. Peut être amélioré avec plus de données.', icon: Target, color: '#10b981' },
  { key: 'f1_score', label: 'F1-Score', desc: 'Moyenne harmonique Precision + Recall : 54.83%. Bon équilibre entre pertinence et couverture.', icon: Activity, color: '#8b5cf6' },
];

export default function ModelMetricsCard({ metrics, detailed }) {
  return (
    <Box sx={{ display: 'grid', gridTemplateColumns: { xs: 'repeat(2, 1fr)', md: 'repeat(4, 1fr)' }, gap: { xs: 1.5, md: 2 } }}>
      {METRICS.map((m) => {
        const val = metrics[m.key] ?? 0;
        const Icon = m.icon;
        return (
          <Tooltip key={m.key} title={m.desc} arrow placement="top">
            <Card sx={{ cursor: 'pointer', '&:hover': { transform: 'translateY(-3px)', transition: 'all 0.25s', boxShadow: `${m.color}20 0 8px 24px` } }}>
              <CardContent sx={{ p: { xs: 1.5, md: 2.5 }, '&:last-child': { pb: { xs: 1.5, md: 2.5 } } }}>
                <Box sx={{ display: 'flex', alignItems: 'flex-start', justifyContent: 'space-between' }}>
                  <Box sx={{ width: 38, height: 38, borderRadius: 2, display: 'flex', alignItems: 'center', justifyContent: 'center', background: `${m.color}15` }}>
                    <Icon size={17} color={m.color} />
                  </Box>
                  <HelpCircle size={14} color="#6b7280" />
                </Box>
                <Typography sx={{ fontSize: { xs: '1.35rem', md: '1.6rem' }, fontWeight: 700, fontFamily: 'monospace', color: m.color, mt: 1 }}>
                  {(val * 100).toFixed(1)}%
                </Typography>
                <Typography sx={{ fontWeight: 600, fontSize: '0.85rem', mt: 0.3 }}>{m.label}</Typography>
                {detailed && <Typography variant="body2" sx={{ fontSize: '0.7rem', mt: 0.3, lineHeight: 1.4 }}>{m.desc}</Typography>}
              </CardContent>
            </Card>
          </Tooltip>
        );
      })}
    </Box>
  );
}
