import { Box, Typography, Card, CardContent } from '@mui/material';
import { CircleDollarSign, ShoppingCart, Package, Users, TrendingUp, TrendingDown } from 'lucide-react';

const CARDS = [
  { key: 'total_revenue', label: 'Revenu Total', icon: CircleDollarSign, suffix: ' MAD', format: (v) => v.toLocaleString('fr-FR'), color: '#f97316', growthKey: 'revenue_growth' },
  { key: 'total_orders', label: 'Commandes Livrées', icon: ShoppingCart, format: (v) => v.toLocaleString('fr-FR'), color: '#6366f1', growthKey: 'orders_growth' },
  { key: 'total_products', label: 'Produits Actifs', icon: Package, format: (v) => v.toLocaleString('fr-FR'), color: '#10b981' },
  { key: 'active_users', label: 'Clients Actifs', icon: Users, format: (v) => v.toLocaleString('fr-FR'), color: '#8b5cf6' },
  { key: 'avg_order_value', label: 'Panier Moyen', icon: CircleDollarSign, suffix: ' MAD', format: (v) => v.toFixed(2), color: '#f59e0b' },
  { key: 'reorder_rate', label: 'Taux de Ré-achat', icon: ShoppingCart, suffix: ' %', format: (v) => (v * 100).toFixed(0), color: '#f43f5e' },
  { key: 'recommendations_generated', label: 'Recommandations Générées', icon: Package, format: (v) => v.toLocaleString('fr-FR'), color: '#06b6d4' },
  { key: 'avg_confidence', label: 'Confiance Moyenne Modèle', icon: TrendingUp, suffix: ' %', format: (v) => (v * 100).toFixed(0), color: '#6366f1' },
];

export default function StatsCards({ stats }) {
  return (
    <Box sx={{ display: 'grid', gridTemplateColumns: { xs: 'repeat(2, 1fr)', sm: 'repeat(3, 1fr)', md: 'repeat(4, 1fr)' }, gap: { xs: 1.5, md: 2 } }}>
      {CARDS.map((card) => {
        const val = stats[card.key] ?? 0;
        const growthVal = card.growthKey ? stats[card.growthKey] : null;
        const isPositive = growthVal !== null && growthVal >= 0;
        return (
          <Card key={card.key} sx={{ '&:hover': { transform: 'translateY(-2px)', transition: 'all 0.2s' } }}>
            <CardContent sx={{ p: { xs: 1.5, md: 2 }, '&:last-child': { pb: { xs: 1.5, md: 2 } } }}>
              <Box sx={{ display: 'flex', alignItems: 'center', justifyContent: 'space-between', mb: 1 }}>
                <Box sx={{ width: 36, height: 36, borderRadius: 2, display: 'flex', alignItems: 'center', justifyContent: 'center', background: `${card.color}15` }}>
                  <card.icon size={16} color={card.color} />
                </Box>
                {growthVal !== null && (
                  <Box sx={{ display: 'flex', alignItems: 'center', gap: 0.3, px: 0.8, py: 0.2, borderRadius: 1, background: isPositive ? 'rgba(16,185,129,0.1)' : 'rgba(239,68,68,0.1)' }}>
                    {isPositive ? <TrendingUp size={12} color="#10b981" /> : <TrendingDown size={12} color="#ef4444" />}
                    <Typography sx={{ fontSize: '0.65rem', fontWeight: 700, color: isPositive ? '#10b981' : '#ef4444' }}>
                      {isPositive ? '+' : ''}{growthVal}%
                    </Typography>
                  </Box>
                )}
              </Box>
              <Typography sx={{ fontSize: { xs: '1.1rem', md: '1.35rem' }, fontWeight: 700, fontFamily: 'monospace', color: card.color }}>
                {card.format(val)}{card.suffix || ''}
              </Typography>
              <Typography variant="body2" sx={{ fontSize: '0.72rem', mt: 0.2 }}>{card.label}</Typography>
            </CardContent>
          </Card>
        );
      })}
    </Box>
  );
}
